    pts.forEach(([px, py], i) => { if (i === 0) return; const s = i % 2 ? 1 : -1; leaves += `<ellipse cx="${(px + s * 6).toFixed(1)}" cy="${py.toFixed(1)}" rx="6.5" ry="3.4" transform="rotate(${s * 35} ${(px + s * 6).toFixed(1)} ${py.toFixed(1)})" style="fill:${i % 3 ? "var(--leaf)" : "var(--leaf2)"}"/>`; if (i % 4 === 2) leaves += `<circle cx="${(px - s * 5).toFixed(1)}" cy="${(py + 4).toFixed(1)}" r="2" class="bloom"/>`; });
    const H = 44 + len * 9 + 8;
