          u.olKey = u.olKey || r.olKey; u.olRating = u.olRating || r.olRating; u.olCount = u.olCount || r.olCount;
          u.pages = u.pages || r.pages; u.year = u.year || r.year; u.subjects = u.subjects?.length ? u.subjects : r.subjects;
          if (!(u.genres || []).length) u.genres = r.genres; if (!(u.themes || []).length) u.themes = r.themes; u.category = u.category || r.category;
