      if ($("#m-verdict")) { const r = $("#m-recto"); if (r) verdict.recommendTo = r.value.trim();
        b.reread = verdict.reread; b.surpriseFav = verdict.surpriseFav || undefined; b.recommend = verdict.recommend || undefined; b.recommendTo = verdict.recommend && verdict.recommendTo ? verdict.recommendTo : undefined; b.hype = verdict.hype; }
      b.genres = list(v("#m-g")); if (rainbowPick !== null) b.rainbow = rainbowPick; b.themes = list(v("#m-th")); b.tropes = list(v("#m-tr")).map(cap);
      b.seriesName = v("#m-se") || null; const sn = parseFloat(v("#m-sn")); b.seriesNum = b.seriesName && !isNaN(sn) ? sn : null;
      if ($("#m-cp")) b.currentPage = parseInt(v("#m-cp")) || 0;
