  const BT_GENRE_NAME = { horror: "horror", romance: "romance", mystery: "mystery", scifi: "sci-fi", fantasy: "fantasy", history: "history", poetry: "poetry", classic: "classic", nonfic: "non-fiction", young: "YA" };
