  let exprT = null, actT = null, lastPoke = Date.now(), lastSaid = "", saidMood = "idle";
  const famCard = () => $("#familiar .famcard");
  function setExpr(e, ms, then){ const card = famCard(); if (!card) return; card.dataset.expr = e; clearTimeout(exprT); if (ms) exprT = setTimeout(() => setExpr(then || saidMood), ms); }
