    const ago = d => { if (!d) return ""; const days = Math.round((new Date(todayISO()) - new Date(String(d).slice(0, 10))) / 864e5); return days <= 0 ? "today" : days === 1 ? "yesterday" : days < 7 ? `${days} days ago` : days < 30 ? `${Math.round(days / 7)} week${days < 14 ? "" : "s"} ago` : `${Math.round(days / 30)} month${days < 60 ? "" : "s"} ago`; };
