      return `<div class="fperson" data-fam="${esc(p.familiar || "cat")}" data-expr="idle">${avatar(p, 48)}<div class="fpinfo"><b>${esc(p.name)}</b><span>@${esc(p.handle)}${p.title ? ` · ${esc(p.title)}` : ""}</span></div>${extra}${btn}</div>`;
