  const sagaOf = b => { const t = `${b.seriesName || ""} | ${b.title || ""}`.toLowerCase(); return SAGAS.find(S => S[2].test(t)) || null; };
  function sagaBookIdx(S, b){
    const clean = x => norm(String(x).split(/[:(]/)[0]).replace(/^(the|a) /, "").trim(), t = clean(b.title || "");
    let i = t ? S[3].findIndex(x => { const n = clean(x); return t === n || t.includes(n) || (t.length > 5 && n.includes(t)); }) : -1;
    if (i < 0 && b.seriesNum) { const n = Math.round(Number(b.seriesNum)), j = (S[0] === "tog" || S[0] === "lotr") ? n : n - 1; if (j >= 0 && j < S[3].length) i = j; }
    return i;
  }
  const sameName = (a, b) => { a = norm(a); b = norm(b); return a === b || a.includes(b) || b.includes(a) || a.split(" ")[0] === b.split(" ")[0] && a.split(" ")[0].length > 3; };
