  const GENRE_SCENE = { "Fantasy": "castle", "Romantasy": "stars", "Romance": "hills", "Science Fiction": "stars", "Mystery": "city", "Thriller": "city", "Horror": "forest", "Historical Fiction": "towers", "Classics": "towers", "Adventure": "sea", "Dystopian": "city", "Young Adult": "hills", "Children's": "hills", "Poetry": "stars", "Literary Fiction": "hills" };
  const darken = (hex, k) => { const [h, s, l] = hexToHsl(hex); return hslToHex(h, s, Math.max(0, l * k)); };
  const lighten = (hex, k) => { const [h, s, l] = hexToHsl(hex); return hslToHex(h, s, Math.min(.92, l + (1 - l) * k)); };
  function cardStyle(c, b){
    const S = SET_STYLE[c?.set] || (c?.set ? null : null) || (() => { const sg = sagaOf(b || {}); return sg ? SET_STYLE[sg[0]] : null; })();
    if (S) return S;
    const col = harmonizeG(lookOf(b || {}).color);
    return { a: darken(col, .62), g: "#E2C27A", sky: [darken(col, .35), lighten(col, .12)], scene: GENRE_SCENE[mainGenreOf(b || {})] || "hills", sym: lookOf(b || {}).motif || "✦", glow: lookOf(b || {}).aura || "#F2D58E" };
  }
