    const heals = [[A, a], [1 - A, f]].map(([side, x]) => { const h = (DUEL_FX[x.st.ability.key] || {}).heal || 0; if (h) d.ink[side] = Math.min(INK, d.ink[side] + h); return h; });
    d.last = { A, a, f, stat, va, vd, win, dmg, hit, heals };
    d.log.push(d.last); d.stage = "reveal";
