    el.querySelector("#rm-end").addEventListener("submit", e => { e.preventDefault(); finishSession(+el.querySelector("#rm-to").value); });
    el.querySelector("#rm-page").addEventListener("submit", e => { e.preventDefault(); rmCheckIn(parseInt(el.querySelector("#rm-pg").value)); });
    el.addEventListener("keydown", e => { if ((e.key === "Enter" || e.key === " ") && e.target.closest?.(".rmfamart")) { e.preventDefault(); e.target.click(); } });
