    const cw = Math.min(220, (SC.W - 240 - (cols - 1) * 24) / cols), chh = cw * 1.5, gridW = cols * cw + (cols - 1) * 24, maxH = 760, scale = Math.min(1, maxH / (rows * chh + (rows - 1) * 24));
