    const authors = topN(list.map(b => b.author).filter(Boolean), 5), fresh = [...new Set(list.map(b => b.author).filter(a => a && !known.has(norm(a))))];
    const durs = list.filter(b => isExact(b.started) && isExact(b.finished) && b.finished >= b.started).map(b => ({ b, d: Math.round((new Date(b.finished) - new Date(b.started)) / 864e5) + 1 })).sort((a, b) => a.d - b.d);
    const MN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    const month = topN(list.filter(b => /^\d{4}-\d{2}/.test(b.finished || "")).map(b => b.finished.slice(5, 7)), 1)[0];
