      genres: topN(list.flatMap(b => [...bookGenres(b)]), 6), tropes: topN(list.flatMap(b => b.tropes || []), 8), feels: topN(list.flatMap(b => b.feelings || []), 5),
      authors, fresh, longest: list.filter(Pg).sort((a, b) => Pg(b) - Pg(a))[0], shortest: list.filter(Pg).sort((a, b) => Pg(a) - Pg(b))[0], fastest: durs[0],
      month: month && month[1] > 1 ? [MN[+month[0] - 1], month[1]] : null, dna: dnaOf(list)[0],
      dnf: books.filter(b => b.shelf === "dnf" && inPeriod(P, b.abandoned)).length,
