    const cov = (b, cls = "") => `<div class="wcov ${cls}">${coverHTML(b)}</div>`;
    const S = [];
    S.push({ a: "#8A4FBF", h: `<div class="wkick">Your ${P.word}${P.live ? " so far" : ""}, wrapped</div><div class="wtitle">${P.q ? `Q${P.q}` : P.y}</div><div class="wsub">${esc(P.span)}</div>
      ${famChosen ? `<div class="wfam">${famArt(familiar)}</div><p class="wsay">“${esc(fam)} has been keeping count. Ready?”</p>` : `<p class="wsay">Let's look back at what you read.</p>`}` });
    const cmp = D.prevN ? (D.n > D.prevN ? `That's ${D.n - D.prevN} more than last ${P.word}.` : D.n === D.prevN ? `Exactly as many as last ${P.word}. Steady as a candle.` : `A gentler ${P.word} than the last (${D.prevN}), and that's fine.`) : "";
