    if (!scanFound) return;
    if (k === "want") { upsert({ ...scanFound, id: newId(), shelf: "want", rating: 0, currentPage: 0, started: null, finished: null, added: new Date().toISOString() }); toast(`${scanFound.title} added to Want to read`); $("#scan-res").hidden = true; $("#scan-view").hidden = false; startCamera(); return; }
