  // ================= the magical tour: your familiar shows you around =================
  const TOUR = [
    { t: "Welcome to your nook", x: f => `Hello, I'm ${f}! This is your own little library. Let me show you around: it only takes a minute, and you can leave whenever you like.` },
    { sel: ".finder", t: "Find a book", x: () => "Type a title or an author and add it to a shelf. ✎ By hand for anything rare, ▥ Scan for a barcode, and ❧ Series adds a whole famous series in the right order." },
    { sel: "#now", t: "Your nightstand", x: () => "The book you're reading lives here. Update your page, light a candle for a cosy reading session with sounds, and look up any word you meet, in any language." },
    { sel: "#bookcase", t: "Your bookcase", x: () => "Tap a spine to open a book. Drag books along or between shelves (on a phone, press and hold first). When a shelf is full, the little stack at its end opens the side shelf." },
    { sel: ".casebtns", t: "Make it yours", x: () => "Customise the theme, the design (gothic, glass, old library…), the fairy lights and a name plank. Decorate with trinkets, see the genre colours, and ↶ Undo if you change your mind." },
    { sel: "#portrait", t: "Your Reader's Soul", x: () => "Every book you finish shapes your Reader DNA: what kind of reader you are, in colours. It shifts with each book and grows levels as you read." },
    { sel: "#room-tabs", prep: () => { try { hallState("grid"); } catch {} }, t: "The rooms of your nook", x: () => "Each door is a room: your Library, a Calendar, your Year in covers, Series, Stats with wrap-ups to share, your Soul with achievements and a passport, books picked For you, Keepsakes with cards, packs and duels, Authors, and Friends with letters." },
    { sel: "#familiar .fambody", t: "And me!", x: f => `Tap me to chat, ask for a book, pet me or bring me a treat. Our bond grows as you read, and unlocks treasures, outfits and one day a legendary mantle. I sometimes leave you gifts, too.` },
    { sel: "#season-btn", t: "Seasons and moods", x: () => "Repaint the whole nook for autumn, winter, spring or summer, and switch between light and dark next to it." },
    { sel: "#sync-pill", t: "Keep it safe", x: () => "Sign in to keep your books safe on every device, and to find friends, visit their nooks and send them books in sealed letters." },
    { sel: "#nook-menu-btn", t: "The little drawer", x: () => "Backups, importing from Goodreads, What's new and this tour all live in here." },
    { t: "That's your nook", end: true, x: f => `Now it's yours to fill. Happy reading! ✦ ${f}` },
  ];
  let tourAt = -1, tourEl = null;
  // on phones the tour walks you through the tabs at the bottom
  const TOUR_TAB = { ".finder": "find", "#now": "nook", "#portrait": "nook", "#bookcase": "shelf", ".casebtns": "shelf", "#familiar .fambody": "nook", "#season-btn": "nook", "#sync-pill": "nook", "#nook-menu-btn": "nook" };
  function tourTarget(st){ if (!st.sel) return null;
    if (document.body.classList.contains("mnav")) { if (st.sel === "#room-tabs") return $("#mtabbar"); const t = TOUR_TAB[st.sel]; if (t && t !== mtab) try { mnavGo(t, null, false); } catch {} }
    const el = document.querySelector(st.sel); if (!el) return null; const r = el.getBoundingClientRect(); return r.width && r.height ? el : null; }
  function placeTour(){
    if (!tourEl || tourAt < 0) return;
    const st = TOUR[tourAt], el = tourTarget(st), spot = tourEl.querySelector(".tspot"), card = tourEl.querySelector(".tcard");
    if (!el) { spot.style.cssText = `left:50%;top:50%;width:0;height:0`; card.classList.add("center"); card.style.cssText = ""; return; }
    const r = el.getBoundingClientRect(), pad = 8, vh = innerHeight, vw = innerWidth;
    const top = Math.max(6, r.top - pad), h = Math.min(vh - 12, r.height + pad * 2);
    spot.style.cssText = `left:${Math.max(6, r.left - pad)}px;top:${top}px;width:${Math.min(vw - 12, r.width + pad * 2)}px;height:${h}px`;
    card.classList.remove("center");
    if (vw < 640) { card.style.cssText = top + h / 2 > vh / 2 ? "top:12px;bottom:auto" : "bottom:12px;top:auto"; return; }
    const below = top + h + 14, ch = card.offsetHeight || 220;
    let y = below + ch < vh - 10 ? below : top - ch - 14; if (y < 10) y = Math.min(vh - ch - 10, Math.max(10, top + 20));
    const x = Math.min(vw - card.offsetWidth - 14, Math.max(14, r.left + r.width / 2 - (card.offsetWidth || 380) / 2));
    card.style.cssText = `left:${x}px;top:${y}px`;
  }
  function showTourStep(i){
    if (i < 0 || i >= TOUR.length) return endTour();
    tourAt = i; const st = TOUR[i]; try { st.prep?.(); } catch {}
    const el = tourTarget(st); if (st.sel && !el) return showTourStep(i + (i >= (showTourStep.last ?? -1) ? 1 : -1));
    showTourStep.last = i;
    const f = famName(familiar), card = tourEl.querySelector(".tcard");
    card.innerHTML = `<div class="tcfam" data-fam="${familiar}" data-expr="${st.end ? "love" : i === 0 ? "happy" : "idle"}">${famArt(familiar)}</div>
      <div class="tcbody"><div class="label">${esc(f)} says · ${i + 1} of ${TOUR.length}</div><h3>${esc(st.t)}</h3><p>${esc(st.x(f))}</p>
        <div class="tcdots">${TOUR.map((_, k) => `<i class="${k === i ? "on" : k < i ? "done" : ""}"></i>`).join("")}</div>
        <div class="tcacts">${i ? `<button type="button" class="btn small" data-tour="back">Back</button>` : `<button type="button" class="linkbtn" data-tour="skip">Maybe later</button>`}
          <button type="button" class="btn small primary" data-tour="next">${st.end ? "✦ Let's read" : i === 0 ? "Show me ✦" : "Next"}</button></div>
        ${i && !st.end ? `<button type="button" class="linkbtn tcskip" data-tour="skip">Skip the tour</button>` : ""}</div>`;
    card.classList.remove("pop"); void card.offsetWidth; card.classList.add("pop");
    tourEl.classList.toggle("noTarget", !el);
    if (el) { el.scrollIntoView({ behavior: "smooth", block: el.offsetHeight > innerHeight * .7 ? "start" : "center" }); setTimeout(placeTour, 420); setTimeout(placeTour, 900); } else placeTour();
    if (st.end) burstTour();
  }
  function burstTour(){ const b = document.createElement("div"); b.className = "tburst"; b.innerHTML = Array.from({ length: 18 }, (_, k) => `<i style="--a:${k * 20}deg;--d:${(k % 3) * .08}s">✦</i>`).join(""); tourEl.append(b); setTimeout(() => b.remove(), 1600); }
  function startTour(){
    endTour(); $("#nook-menu") && ($("#nook-menu").hidden = true); $("#modal-root").innerHTML = "";
    tourEl = document.createElement("div"); tourEl.id = "tour"; tourEl.setAttribute("role", "dialog"); tourEl.setAttribute("aria-label", "A tour of your nook");
    tourEl.innerHTML = `<div class="tspot"><i class="ts1">✦</i><i class="ts2">✧</i><i class="ts3">✦</i></div><div class="tcard"></div>`;
    document.body.append(tourEl); document.body.classList.add("touring");
    tourEl.addEventListener("click", e => { const b = e.target.closest("[data-tour]"); if (!b) return; const k = b.dataset.tour; if (k === "next") TOUR[tourAt].end ? endTour(true) : showTourStep(tourAt + 1); else if (k === "back") showTourStep(tourAt - 1); else endTour(); });
    addEventListener("resize", placeTour); addEventListener("scroll", placeTour, { passive: true }); document.addEventListener("keydown", tourKey);
    showTourStep(0); lsSet("reading-ledger-toured", true);
  }
  function tourKey(e){ if (!tourEl) return; if (e.key === "Escape") endTour(); else if (e.key === "ArrowRight") showTourStep(tourAt + 1); else if (e.key === "ArrowLeft") showTourStep(tourAt - 1); }
  function endTour(done){ if (!tourEl) return; tourEl.remove(); tourEl = null; tourAt = -1; document.body.classList.remove("touring"); removeEventListener("resize", placeTour); removeEventListener("scroll", placeTour); document.removeEventListener("keydown", tourKey); if (done) { try { hallState("closed"); } catch {} scrollTo({ top: 0, behavior: "smooth" }); toast("✦ Enjoy your nook", 2000); } }
  document.addEventListener("click", e => { if (e.target.closest("[data-starttour]")) { e.preventDefault(); startTour(); } });
  const KEY_SEENVER = "reading-ledger-seenver";
  function openChangelog(){
    const root = $("#modal-root");
    root.innerHTML = `<div class="scrim" id="cl-scrim"><div class="modal clmodal" role="dialog" aria-modal="true" aria-labelledby="cl-title">
      <div class="label">My Book Nook · version ${APP_VERSION}</div><h2 id="cl-title">What's new</h2>
      <button type="button" class="tourcta" data-starttour><span class="tcico">🗝</span><span><b>Take the magical tour</b><small>${esc(famName(familiar))} shows you everything your nook can do, in a minute</small></span><span aria-hidden="true">→</span></button>
      <div class="cllist">${CHANGELOG.map(([v, d, t, items], i) => `<section class="clv${i === 0 ? " now" : ""}"><div class="clhead"><span class="clnum">v${v}</span><b>${esc(t)}</b>${d ? `<small>${d}</small>` : ""}</div><ul>${items.map(x => `<li>${esc(x)}</li>`).join("")}</ul></section>`).join("")}</div>
      <p class="note">Tip: if a friend's nook looks different from yours, compare version numbers. Closing and reopening the app picks up the newest one.</p>
      <div class="mfoot"><button class="btn primary" type="button" id="cl-done">Lovely</button></div></div></div>`;
    $("#cl-scrim").addEventListener("click", e => { if (e.target.id === "cl-scrim" || e.target.id === "cl-done") root.innerHTML = ""; });
    lsSet(KEY_SEENVER, APP_VERSION);
  }
  document.addEventListener("click", e => { const r = e.target.closest("[data-recommend]"); if (r) { const id = r.dataset.recommend; $("#modal-root").innerHTML = ""; Social.compose({ bookId: id }); } });
  document.addEventListener("click", e => { if (e.target.closest("[data-whatsnew]")) { e.preventDefault(); const m = $("#nook-menu"); if (m) m.hidden = true; openChangelog(); } });
  // after an update, a gentle note (new friends just start at the current version)
  setTimeout(() => { try {
    const seen = lsGet(KEY_SEENVER, null);
    if (seen === APP_VERSION) return;
    if (!seen && !books.length) { lsSet(KEY_SEENVER, APP_VERSION); return; }
    const el = document.createElement("div"); el.className = "verbanner"; el.innerHTML = `<span>✦ My Book Nook was updated to <b>v${APP_VERSION}</b></span><button type="button" class="btn small primary" data-whatsnew>See what's new</button><button type="button" class="iconbtn" aria-label="Dismiss">✕</button>`;
    el.addEventListener("click", e => { if (e.target.closest(".iconbtn") || e.target.closest("[data-whatsnew]")) { lsSet(KEY_SEENVER, APP_VERSION); el.remove(); } });
    document.body.append(el); setTimeout(() => { el.style.transition = "opacity .6s"; el.style.opacity = 0; setTimeout(() => el.remove(), 700); }, 15000);
  } catch {} }, 2500);
  function render(){
    renderNow(); renderShelf(); renderPortrait(); renderLibrary(); if (typeof renderGuide === "function") renderGuide();
    setTimeout(fillSpineColors, 300);
    if (tab === "calendar") renderCalendar();
    if (tab === "covers") renderCovers();
    if (tab === "series") renderSeries();
    if (tab === "stats") renderStats();
    if (tab === "soul" && !document.activeElement?.closest?.("#view-soul input")) renderSoul();
    if (tab === "keep" && !$("#modal-root").innerHTML.trim()) renderKeep();
    if (tab === "recs" && document.activeElement?.id !== "rec-mood") renderRecs();
    if (lastResults.length && $("#results-wrap .results")) renderResultsArea("list");
  }
  // the rooms stay folded away until you open Explore your nook
  function hallState(st){ document.body.classList.remove("hall-closed", "hall-grid", "hall-room"); document.body.classList.add("hall-" + st); $("#hall-btn")?.setAttribute("aria-expanded", st !== "closed");
    const sub = $("#hall-sub"); if (sub) sub.textContent = st === "closed" ? "Your library, stats, soul, keepsakes and friends" : st === "grid" ? "Pick a room below" : "You're in a room below"; const cta = $("#hall-cta"); if (cta) cta.innerHTML = st === "closed" ? `Tap to open the rooms <b class="hallchev">▾</b>` : `Close the rooms <b class="hallchev">▴</b>`; }
  hallState("closed");
  $("#hall-btn").addEventListener("click", () => { const open = !document.body.classList.contains("hall-closed"); hallState(open ? "closed" : "grid"); if (open) $(".hall")?.scrollIntoView({ behavior: "smooth", block: "start" }); });
  function showTab(t){
    tab = t; hallState("room");
    for (const k of TABS) { $("#tab-" + k).setAttribute("aria-selected", k === t); $("#view-" + k).hidden = k !== t; }
    if (t !== "stats") destroyCharts();
    ({ calendar: renderCalendar, covers: renderCovers, series: renderSeries, stats: renderStats, soul: renderSoul, recs: renderRecs, keep: renderKeep, authors: renderAuthors, friends: () => Social.show() })[t]?.();
    try { mnavFollow(t); } catch {}
  }
  const openById = id => { const b = books.find(x => x.id === id); if (b) openEditor(b, false); };
  document.addEventListener("keydown", e => { if (e.key === "Escape") ($("#m-cancel") || $("#s-cancel"))?.click(); });
  document.addEventListener("click", e => {
    const op = e.target.closest("[data-open]");
    if (op && !e.target.closest("#modal-root")) { openById(op.dataset.open); return; }
  });
  $("#search-form").addEventListener("submit", e => { e.preventDefault(); runSearch($("#q").value); });
  $("#manual-btn").addEventListener("click", () => openEditor({ title: $("#q").value.trim() }, true));
  $("#scan-btn").addEventListener("click", openScanner);
  document.addEventListener("click", e => {
    if (e.target.closest("[data-famjar]")) { openJar(); return; }
    if (e.target.closest("[data-releases]")) { openReleases(); return; }
    if (e.target.closest("[data-bond]")) { openBond(); return; }
  });
  setTimeout(bondVisit, 1500);
  $("#series-add-btn").addEventListener("click", () => openSeriesAdder());
  $("#results-wrap").addEventListener("click", e => {
    const chip = e.target.closest("[data-q]"); if (chip) { $("#q").value = chip.dataset.q; return runSearch(chip.dataset.q); }
    if (e.target.closest("[data-close]")) return closeResults();
    if (e.target.closest("[data-manual]")) return openEditor({ title: lastQuery }, true);
    const add = e.target.closest("[data-add]"); if (add) return openEditor({ ...lastResults[+add.dataset.add] }, true);
    const ask = e.target.closest("[data-askfam]");
    if (ask) { const row = ask.closest(".row"), ex = row.querySelector(".famsay"); if (ex) { ex.remove(); return; } row.querySelector(".meta").insertAdjacentHTML("beforeend", famBubble({ ...lastResults[+ask.dataset.askfam], shelf: "want" })); return; }
    const as = e.target.closest("[data-addseries]"); if (as) { const r = lastResults[+as.dataset.addseries], S = catalogForBook(r); return openSeriesAdder(S ? { name: S.name, author: S.author } : { name: r.seriesHint, author: r.author, title: r.title }); }
    const sca = e.target.closest("[data-scatadd]"); if (sca) { const S = SERIES_CAT.find(x => x.name === sca.dataset.scatadd); if (S) return openSeriesAdder({ name: S.name, author: S.author }); }
  });
  $("#tools").addEventListener("click", e => { if (e.target.id === "fetch-btn") fetchMissing(); if (e.target.id === "trope-btn") findTropesAll(); });
